


/** Independent funding resource. Value and consideration are separate. External funding and import provenance are merchant-attested; no payment is collected by recording them. Replacement refund lots retain original funding provenance and do not represent new paid funding. */ export type GiftCardLoadInput = { "consideration_money"?: never; /** RFC3339 timestamp. Format: date-time. */ "created_at"?: never; /** Restrictions tied to original funding, including value restored to replacement cards. A win clears only its own restriction. A loss keeps spending restricted until you create a gift card funding disposition. */ "funding_disputes"?: never; "gift_card_id"?: never; "gift_card_load_id"?: never; "idempotency_key"?: never; /** Pending original cash refunds holding unspent value on this descendant funding lot. Unknown provider outcomes retain these holds. */ "purchase_refund_value_holds"?: never; /** Cash refunds and manual payment reversals against this original funding load. Pending refunds reserve their value; confirmed success removes it, and confirmed failure releases the hold. */ "purchase_refunds"?: never; "purchase_restoration"?: never; "refund_provenance"?: never; /** Monetary amount represented as integer minor units plus an ISO 4217 currency code. */ "refund_transferred_money"?: never; /** Monetary amount represented as integer minor units plus an ISO 4217 currency code. */ "remaining_money"?: never; /** Monetary amount represented as integer minor units plus an ISO 4217 currency code. */ "reversed_money"?: never; "source"?: never; /** RFC3339 timestamp. Format: date-time. */ "source_created_at"?: never; /** Monetary amount represented as integer minor units plus an ISO 4217 currency code. */ "value_money"?: never; /** Use an exact numeric string, not a floating-point number. Format: int64. */ "version"?: never; };
